"use strict";

/**
 * v3.5.5 (3P Matrix 4.5.4 parity): this list ships as a precompiled JSON string in Brands.default.js,
 * generated by tools/gen-data-defaults.mjs from data/Brands.json, and is parsed on its first
 * lookup (util/LazyJson.js) — never at service-worker start.
 *
 * Brands.js — the ONE shared brand/real-website list for every
 * brand-impersonation check (3P Matrix alignment §2, v3.2.0).
 *
 * Replaces two lists that grew separately and disagreed (SketchyUrlCheck's
 * 113-entry BRANDS table and BrandDomains.json's 22 entries — 7 of which
 * weren't in the 113) with one: data/Brands.json, generated by
 * tools/gen-brands-data.mjs from the merged/regionally-extended table (see
 * that script's header for the full provenance). Same default/remote split
 * as every other extracted-data module (SuspiciousDomainsDefaultJson,
 * TopSitesFilterDefaultJson, ...) — see PublicSuffixList.js's header for the
 * full rationale.
 *
 * Shape: the parsed BrandsDefaultJson is an array of
 *   { keyword, domains: [real website(s)], exceptions?: [...], wholeNameOnly?: true }
 * — domains is plural because the same brand keyword often has several
 * real country-specific websites (e.g. "ing" -> ing.nl/ing.de/ing.be/ing.pl).
 *
 * Two independent matching modes, both consumed by two different callers:
 *
 *   matchBrand(host) / matchBrandFuzzy(host) — today's SketchyUrlCheck.js
 *   checks 4/4a ("is this LIVE, unconverted hostname impersonating a brand
 *   right now"): wholeNameOnly keywords only match when the host's whole
 *   registrable name IS the keyword; other keywords match as a separate
 *   word anywhere in the host (split on "." and "-" — not a bare substring,
 *   so "google" no longer matches "googleusercontent"). Fuzzy (edit-
 *   distance) only runs for keywords of >= FUZZY_MIN_BRAND_LENGTH letters.
 *
 *   matchWordAgainstBrands(words) — protection/LookalikeDomainCheck.js's
 *   test 3 ("separate words of an already imitation-converted variant
 *   against the brand list"): a plain exact-word lookup, no wholeNameOnly
 *   distinction needed (splitting into words already makes any match a
 *   whole-word match) and no fuzzy (test 3 only ever compares a candidate
 *   that's already gone through test 2's character conversion).
 *
 * Government-suffix brands (impots, ameli, elster, irs, sat, ...) are
 * ordinary keyword entries like any other — only the SUFFIX itself
 * (gov.uk, gob.mx, ...) is special-cased, and that lives in GovSuffixes.js,
 * not here (see that module's header).
 */
import { BrandsDefaultJson } from "./Brands.default.js";
import { lazyJson } from "./LazyJson.js";
import { UrlUtils } from "./UrlUtils.js";

export const Brands = (function () {

    // Edit-distance tuning for matchBrandFuzzy() — same project convention
    // as SketchyUrlCheck.js previously had inline; now lives here since two
    // modules need identical behaviour. v3.2.0 (3P Matrix alignment §2.3):
    // minimum keyword length raised 5 -> 7 — measured false-alarm rate on a
    // 215,348-site CrUX sample found the remaining 5-6 letter noise
    // ("linkt"->"link", "mbank"->"bank", "shopify"<->"spotify" — no, that
    // pair is 7 letters and still a known accepted gap, see below)
    // disappears once only keywords of 7+ letters are allowed to fuzzy-match.
    const FUZZY_MIN_BRAND_LENGTH   = 7;
    const FUZZY_MAX_EDIT_DISTANCE  = 2;
    const FUZZY_LONG_KEYWORD_LENGTH = 7; // keywords at/above this length get the full ceiling; this
                                           // project only ever defines FUZZY_MIN_BRAND_LENGTH ==
                                           // FUZZY_LONG_KEYWORD_LENGTH now (both 7), so every keyword
                                           // that is eligible for fuzzy matching at all already gets
                                           // the full ceiling — kept as a separate constant anyway so
                                           // the two concepts ("eligible at all" vs "how loose once
                                           // eligible") stay independently tunable, same as before.
    const FUZZY_MAX_LENGTH_DELTA    = 2;

    // Extremely common subdomain labels, excluded from fuzzy brand matching
    // (ported verbatim from SketchyUrlCheck.js — see that file's former
    // header/CHANGELOG for the "app.zoominfo.com" false-positive this fixed).
    const FUZZY_EXCLUDED_LABELS = new Set([
        "www", "app", "api", "cdn", "ftp", "mail", "shop", "blog", "help",
        "docs", "dev", "test", "staging", "admin", "portal", "secure",
        "login", "account", "my", "get", "download", "dl", "static",
        "assets", "img", "images", "m", "mobile", "beta", "news", "support",
        "care", "chat", "jobs", "web", "go", "id", "auth", "sso",
        "cloud", "team", "store", "data", "service", "services", "hub",
        "group", "world", "live", "media", "central"
    ]);

    // ── In-memory state — rebuilt wholesale by setData()/resetToDefault() ──
    let list        = null; // [{keyword, domains, exceptions, wholeNameOnly}]
    let keywordSet  = null; // Set<string> — every keyword, for matchWordAgainstBrands()
    let byKeyword   = null; // Map<keyword, brand>
    let exemptDomainsSet = null; // every domains[]/exceptions[] entry — real sites, never flagged

    function loadFrom(data) {
        list       = data;
        keywordSet = new Set();
        byKeyword  = new Map();
        exemptDomainsSet = new Set();
        for (const brand of list) {
            keywordSet.add(brand.keyword);
            byKeyword.set(brand.keyword, brand);
            for (const d of brand.domains)            exemptDomainsSet.add(d);
            for (const e of (brand.exceptions || []))  exemptDomainsSet.add(e);
        }
    }
    // 3P Matrix 4.5.4 (perf P4): built on the first lookup, not at service-worker start (util/LazyJson.js).
    const defaultData = lazyJson(BrandsDefaultJson);
    function ensureLoaded()      { if (list === null) loadFrom(defaultData()); }   // guard: never queried with "no data yet"

    function setData(newData)    { loadFrom(newData); }
    function resetToDefault()    { list = keywordSet = byKeyword = exemptDomainsSet = null; }   // released; rebuilt on next use

    /**
     * True when `host` IS one of the brands' own real domains, or a
     * subdomain of one — the single early-out shared by both matching
     * modes below (a real, known-legitimate brand domain can never be
     * "impersonating" anything, even a different brand it happens to
     * coincidentally resemble — see SketchyUrlCheck.js's former
     * isKnownLegitimateBrandHost() for the shopify.com/"spotify" and
     * cisco.com/"costco" cases this specifically guards).
     */
    function isExemptHost(host) {
        ensureLoaded();
        if (exemptDomainsSet.has(host)) return true;
        for (const d of exemptDomainsSet) {
            if (host.endsWith("." + d)) return true;
        }
        return false;
    }

    function wordsOf(host) {
        return host.split(/[.-]/).filter(Boolean);
    }

    /**
     * Today's SketchyUrlCheck check-4 equivalent: is `host` impersonating
     * some brand right now, as-is (no imitation-character conversion)?
     * Returns { keyword, brand } or null.
     *
     * A keyword that itself contains a dot (e.g. "booking.com" — a handful
     * of brand entries are deliberately the *full* brand context rather
     * than a bare word, to avoid flagging ordinary use of a common English
     * word; see Brands.json/gen-brands-data.mjs) can never appear as one
     * split WORD (splitting on "." would break it apart), so that case
     * stays a substring check instead — this is exactly what catches the
     * "booking.com.evil-login.net" subdomain-prefix trick.
     */
    function matchBrand(host) {
        ensureLoaded();
        if (!host || isExemptHost(host)) return null;

        const registeredDomain = UrlUtils.getRegisteredDomain(host) || host;
        const firstDot  = registeredDomain.indexOf(".");
        const namePart  = firstDot > 0 ? registeredDomain.slice(0, firstDot) : registeredDomain;
        const words     = wordsOf(host);

        for (const brand of list) {
            if (brand.keyword.includes(".")) {
                if (host.includes(brand.keyword)) return { keyword: brand.keyword, brand };
            } else if (brand.wholeNameOnly) {
                if (namePart === brand.keyword) return { keyword: brand.keyword, brand };
            } else if (words.includes(brand.keyword)) {
                return { keyword: brand.keyword, brand };
            }
        }
        return null;
    }

    function levenshtein(a, b) {
        const rows = a.length + 1, cols = b.length + 1;
        const dp = Array.from({ length: rows }, () => new Array(cols).fill(0));
        for (let i = 0; i < rows; i++) dp[i][0] = i;
        for (let j = 0; j < cols; j++) dp[0][j] = j;
        for (let i = 1; i < rows; i++) {
            for (let j = 1; j < cols; j++) {
                dp[i][j] = a[i - 1] === b[j - 1]
                    ? dp[i - 1][j - 1]
                    : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
            }
        }
        return dp[rows - 1][cols - 1];
    }

    function maxAllowedDistance(keywordLength) {
        return keywordLength >= FUZZY_LONG_KEYWORD_LENGTH ? FUZZY_MAX_EDIT_DISTANCE : 1;
    }

    /**
     * Today's SketchyUrlCheck check-4a equivalent: a near-miss (1-2 edit
     * distance) typo of some brand keyword used as a whole dot-separated
     * label, for brands of >= FUZZY_MIN_BRAND_LENGTH letters only (see
     * header comment on the 5 -> 7 raise). Returns { keyword, brand } or
     * null. Does not re-check brands matchBrand() already matched exactly
     * — callers skip calling this for a brand once matchBrand() has fired.
     */
    function matchBrandFuzzy(host) {
        ensureLoaded();
        if (!host || isExemptHost(host)) return null;
        const labels = host.split(".");

        for (const brand of list) {
            if (brand.keyword.length < FUZZY_MIN_BRAND_LENGTH) continue;
            for (const label of labels) {
                if (label === brand.keyword) continue; // exact — matchBrand() already covers this
                if (FUZZY_EXCLUDED_LABELS.has(label)) continue;
                if (label.length < 3) continue;
                if (Math.abs(label.length - brand.keyword.length) > FUZZY_MAX_LENGTH_DELTA) continue;

                const distance = levenshtein(label, brand.keyword);
                if (distance >= 1 && distance <= maxAllowedDistance(brand.keyword.length)) {
                    return { keyword: brand.keyword, brand };
                }
            }
        }
        return null;
    }

    /**
     * protection/LookalikeDomainCheck.js's test 3: does any of `words`
     * (already split on "." and "-" by the caller) exactly equal a brand
     * keyword? Plain Set lookup — no wholeNameOnly distinction (splitting
     * into words already makes any hit a whole-word match) and no fuzzy
     * (test 3 only ever runs against a candidate that already went through
     * test 2's imitation-character conversion).
     */
    function matchWordAgainstBrands(words) {
        ensureLoaded();
        for (const word of words) {
            if (keywordSet.has(word)) return { keyword: word, brand: byKeyword.get(word) };
        }
        return null;
    }

    return {
        matchBrand,
        matchBrandFuzzy,
        matchWordAgainstBrands,
        isExemptHost,
        wordsOf,
        setData,
        resetToDefault,
        get list() { ensureLoaded(); return list; },
    };
})();
